export default function bitcoinMetrics({ payload }) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('CoinPaprika response must be an object.');
  const move24 = payload.quotes?.USD?.percent_change_24h;
  if (!Number.isFinite(move24)) throw new Error('Missing or nonnumeric Bitcoin 24-hour change.');
  return { payload, move24 };
}

