export default function bitcoinMessage({ payload }) {
  const usd = payload?.quotes?.USD;
  for (const field of ['price', 'percent_change_24h', 'percent_change_7d']) if (!Number.isFinite(usd?.[field])) throw new Error('Missing or nonnumeric Bitcoin metric: ' + field);
  return { text: `Bitcoin big 24h move alert

Price: $${usd.price.toFixed(2)}
24h change: ${usd.percent_change_24h.toFixed(2)}%
7d change: ${usd.percent_change_7d.toFixed(2)}%

Source: CoinPaprika (keyless, no API key)` };
}
